import { Block } from '../block';
import type { CurrentMenu } from '../field/current-menu';
import type { DragMode } from '../field/drag-mode';
import type { Key } from '../field/key';
import { Input } from '../input';

/**
 * Typed factories for Scratch "Sensing" blocks.
 *
 * Generated by bin/generate-blocks.ts — do not edit by hand.
 */
export const Sensing = {
  touchingObject(touchingobjectmenu: string | Block): Block {
    return Block.make('sensing_touchingobject')
      .input('TOUCHINGOBJECTMENU', Input.menu('sensing_touchingobjectmenu', 'TOUCHINGOBJECTMENU', touchingobjectmenu));
  },

  touchingColor(color: string | Input): Block {
    return Block.make('sensing_touchingcolor')
      .input('COLOR', typeof color === 'string' ? Input.color(color) : color);
  },

  colorIsTouchingColor(color: string | Input, color2: string | Input): Block {
    return Block.make('sensing_coloristouchingcolor')
      .input('COLOR', typeof color === 'string' ? Input.color(color) : color)
      .input('COLOR2', typeof color2 === 'string' ? Input.color(color2) : color2);
  },

  distanceTo(distancetomenu: string | Block): Block {
    return Block.make('sensing_distanceto')
      .input('DISTANCETOMENU', Input.menu('sensing_distancetomenu', 'DISTANCETOMENU', distancetomenu));
  },

  askAndWait(question: string | Block | Input): Block {
    return Block.make('sensing_askandwait')
      .input('QUESTION', question);
  },

  answer(): Block {
    return Block.make('sensing_answer');
  },

  keyPressed(keyOption: Key | Block): Block {
    return Block.make('sensing_keypressed')
      .input('KEY_OPTION', Input.menu('sensing_keyoptions', 'KEY_OPTION', keyOption));
  },

  mouseDown(): Block {
    return Block.make('sensing_mousedown');
  },

  mouseX(): Block {
    return Block.make('sensing_mousex');
  },

  mouseY(): Block {
    return Block.make('sensing_mousey');
  },

  setDragMode(dragMode: DragMode): Block {
    return Block.make('sensing_setdragmode')
      .field('DRAG_MODE', dragMode);
  },

  loudness(): Block {
    return Block.make('sensing_loudness');
  },

  loud(): Block {
    return Block.make('sensing_loud');
  },

  timer(): Block {
    return Block.make('sensing_timer');
  },

  resetTimer(): Block {
    return Block.make('sensing_resettimer');
  },

  of(object: string | Block, property: string): Block {
    return Block.make('sensing_of')
      .input('OBJECT', Input.menu('sensing_of_object_menu', 'OBJECT', object))
      .field('PROPERTY', property);
  },

  current(currentmenu: CurrentMenu): Block {
    return Block.make('sensing_current')
      .field('CURRENTMENU', currentmenu);
  },

  daysSince2000(): Block {
    return Block.make('sensing_dayssince2000');
  },

  username(): Block {
    return Block.make('sensing_username');
  },

  userId(): Block {
    return Block.make('sensing_userid');
  }
};
